                                    if order.asset.symbol[:3] == '300' and trading_date >= gem_change_date:
                                        if order.type == OrderType.MARKET.value:
                                            market_upper_amount = self._engine.config.plugins.plugin_system_risk_control.market_upper_amount
                                            if amount > market_upper_amount:
                                                strategy_log.warning(_('市价单下单超过交易所规定最高{}股限制，取消下单').format(market_upper_amount))
